import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

class DashboardPage extends StatefulWidget {
  const DashboardPage({super.key});

  @override
  State<DashboardPage> createState() => _DashboardPageState();
}

class _DashboardPageState extends State<DashboardPage> {
  late final Future<void> _loadDataFuture;
  List<CurrencyModel> _currencies = [];
  List<NewsModel> _news = [];

  @override
  void initState() {
    super.initState();
    _loadDataFuture = _initData();
  }

  Future<void> _initData() async {
    final currencyRepository = context.read<CurrencyRepository>();
    final newsRepository = context.read<NewsRepository>();

    await Future.wait([
      currencyRepository.fetchRates(const CurrencyPageRequest(base: 'USD', page: 0, pageSize: 20)).then(
        (CurrencyPage page) {
          if (mounted) {
            setState(() => _currencies = page.items);
          }
        },
      ),
      newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)).then((List<NewsModel> news) {
        if (mounted) {
          setState(() => _news = news);
        }
      }),
    ]);
  }

  @override
  Widget build(BuildContext context) {
    final AppLocalizations loc = context.loc;

    return Scaffold(
      appBar: AppBar(title: Text(loc.dashboard)),
      body: FutureBuilder<void>(
        future: _loadDataFuture,
        builder: (BuildContext context, AsyncSnapshot<void> snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting && _currencies.isEmpty && _news.isEmpty) {
            return const Center(child: CircularProgressIndicator());
          }

          final List<Widget> children = <Widget>[];

          if (_currencies.isNotEmpty) {
            children.add(Padding(
              padding: const EdgeInsets.fromLTRB(22, 16, 22, 8),
              child: Text(loc.currencyRate, style: Theme.of(context).textTheme.titleLarge),
            ));
            for (final CurrencyModel currency in _currencies) {
              children.add(CurrencyCard(model: currency));
            }
          }

          if (_news.isNotEmpty) {
            children.add(const SizedBox(height: 16));
            children.add(Padding(
              padding: const EdgeInsets.fromLTRB(22, 0, 22, 8),
              child: Text(loc.news, style: Theme.of(context).textTheme.titleLarge),
            ));
            for (final NewsModel newsItem in _news) {
              children.add(NewsCard(model: newsItem));
            }
          }

          if (children.isEmpty) {
            return const Center(child: Text('No data'));
          }

          return ListView(children: children, padding: const EdgeInsets.fromLTRB(22, 0, 22, 40));
        },
      ),
    );
  }
}
