{"content":"import 'package:flutter/material.dart';
import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

class DashboardPage extends StatefulWidget {
  const DashboardPage({super.key});

  @override
  State<DashboardPage> createState() => _DashboardPageState();
}

class _DashboardPageState extends State<DashboardPage> {
  late final Future<void> _loadDataFuture;
  List<CurrencyModel> _currencies = [];
  List<NewsModel> _news = [];

  @override
  void initState() {
    super.initState();
    _loadDataFuture = _initData();
  }

  Future<void> _initData() async {
    final currencyRepository = context.read<CurrencyRepository>();
    final newsRepository = context.read<NewsRepository>();

    await Future.wait([
      currencyRepository.fetchRates(const CurrencyPageRequest(base: 'USD', page: 0, pageSize: 20)).then(
        (CurrencyPage page) {
          if (mounted) {
            setState(() => _currencies = page.items);
          }
        },
      ),
      newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)).then((List<NewsModel> news) {
        if (mounted) {
          setState(() => _news = news);
        }
      }),
    ]);
  }

  @override
  Widget build(BuildContext context) {
    final AppLocalizations loc = context.loc;

    return Scaffold(
      appBar: AppBar(title: Text(loc.dashboard)),
      body: FutureBuilder<void>(
        future: _loadDataFuture,
        builder: (BuildContext context, AsyncSnapshot<void> snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting && _currencies.isEmpty && _news.isEmpty) {
            return const Center(child: CircularProgressIndicator());
          }

          final List<Widget> children = <Widget>[];

          if (_currencies.isNotEmpty) {
            children.add(Padding(
              padding: const EdgeInsets.fromLTRB(22, 16, 22, 8),
              child: Text(loc.currencyRate, style: Theme.of(context).textTheme.titleLarge),
            ));
            for (final CurrencyModel currency in _currencies) {
              children.add(_buildCurrencyCard(currency));
            }
          }

          if (_news.isNotEmpty) {
            children.add(const SizedBox(height: 16));
            children.add(Padding(
              padding: const EdgeInsets.fromLTRB(22, 0, 22, 8),
              child: Text(loc.news, style: Theme.of(context).textTheme.titleLarge),
            ));
            for (final NewsModel newsItem in _news) {
              children.add(_buildNewsCard(newsItem));
            }
          }

          if (children.isEmpty) {
            return const Center(child: Text('No data'));
          }

          return ListView(children: children, padding: const EdgeInsets.fromLTRB(22, 0, 22, 40));
        },
      ),
    );
  }

  Widget _buildCurrencyCard(CurrencyModel model) {
    final PriceChange priceChange = model.asPriceChange;
    final ThemeFonts fonts = context.fonts;
    final ThemeColors colors = context.colors;

    return GestureDetector(
      onTap: () {
        Navigator.push<void>(
          context,
          PageRouteBuilder(
            pageBuilder: (BuildContext context, Animation<double> animation, Animation<double> secondaryAnimation) {
              return CurrencyDetailPage(title: model.name);
            },
            transitionsBuilder: (context, animation, secondaryAnimation, child) {
              const Cubic curve = Curves.ease;
              final Animatable<Offset> tween = Tween<Offset>(begin: Offset(1.0, 0.0), end: Offset.zero).chain(CurveTween(curve: curve));
              return SlideTransition(position: animation.drive(tween), child: child);
            },
          ),
        );
      },
      child: Container(
        margin: const EdgeInsets.symmetric(vertical: 4),
        padding: const EdgeInsets.symmetric(vertical: 14, horizontal: 8),
        decoration: BoxDecoration(
          color: colors.cardColor,
          borderRadius: BorderRadius.circular(12),
        ),
        child: Row(
          children: [
            Container(
              constraints: BoxConstraints.tight(Size.square(40)),
              decoration: BoxDecoration(
                color: colors.currencyCardSymbolBackground,
                shape: BoxShape.circle,
              ),
              child: Center(
                child: Text(model.symbol, style: fonts.semiBold12.copyWith(color: Colors.white)),
              ),
            ),
            const SizedBox(width: 8),
            Expanded(
              child: Padding(
                padding: const EdgeInsets.symmetric(horizontal: 6),
                child: Text(model.name, style: fonts.semiBold12),
              ),
            ),
            Text(
              model.value.toStringAsFixed(2),
              style: fonts.semiBold12.copyWith(
                color: switch (priceChange) {
                  PriceChange.up => colors.greenWrasse,
                  PriceChange.down => colors.red,
                  PriceChange.stable => colors.stormyGrey,
                },
              ),
            ),
            Padding(
              padding: const EdgeInsets.only(left: 4, right: 6),
              child: Text(context.loc.asNominal(model.nominal), style: fonts.regular12),
            ),
            Image.asset(
              switch (priceChange) {
                PriceChange.up => 'assets/icons/arrow_up.png',
                PriceChange.down => 'assets/icons/arrow_down.png',
                PriceChange.stable => 'assets/icons/arrow_up.png',
              },
              width: 10,
              height: 10,
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildNewsCard(NewsModel model) {
    final DateTime? date = model.date;
    final ThemeFonts fonts = context.fonts;
    final ThemeColors colors = context.colors;

    return GestureDetector(
      onTap: () => tryLaunchUrl(model.link),
      child: Container(
        margin: const EdgeInsets.symmetric(vertical: 4),
        padding: const EdgeInsets.symmetric(vertical: 12, horizontal: 18),
        decoration: BoxDecoration(
          color: colors.cardColor,
          borderRadius: BorderRadius.circular(12),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(model.title, style: fonts.semiBold12),
            Padding(
              padding: const EdgeInsets.only(top: 6),
              child: Row(
                mainAxisAlignment: MainAxisAlignment.spaceBetween,
                children: [
                  if (date != null)
                    Text(DateFormat('dd.MM.yyyy HH:mm').format(date), style: fonts.regular12.copyWith(color: colors.tin)),
                  Text('cbr.ru', style: fonts.regular12.copyWith(color: colors.tin)),
                ],
              ),
            )
          ],
        ),
      ),
    );
  }
}
